-- Generated by NCWE Studio from the world project "NCM Build Kit".
-- The package is preloaded as the required mod "ncm_build_kit-assets": the launcher installs it
-- before Cyberpunk starts. Changing it needs a dedicated-server restart, then a fresh game launch.
resource "ncm_build_kit"
version "1.0.0"
auto_start true

-- NCM Build (IDEA-1282 / IDEA-1307): the starter kit's meshes (strut, beam, panels, wall, wings, fin, wheel pod, nozzle
-- housings, tank, controller), cooked by NCWE from tools/deep/ncwe/build-build-kit.py. NCM Sky's kit templates (kinds
-- 15+) draw them attached to Machines; ncm_build is the authority for what is attached where.

-- (KB-409: the exported `dependency "archivexl"` line is removed -- it aborts every resource's auto-start; ArchiveXL is a required mod already)
preload_mod "dist/ncm-build-kit.zip"

server_script "server/main.lua"
